import { component$ } from "@qwik.dev/core";
import { routeLoader$, type DocumentHead } from "@qwik.dev/router";
import { LuCircleDot } from "@qwikest/icons/lucide";
import { getSourceCounts } from "~/catalog";
import { ALL_PACKAGE_SOURCE_IDS, SOURCE_LABELS, type PackageSourceId } from "~/catalog-types";
import todos from "~/data/source-todos.json";
import { resolveServerEnv } from "~/server-env";

// Generated by `pnpm sync:source-todos` from tuxery/catalog's open issues
// labelled `source:<id>` — see scripts/sync-source-todos.ts. Never edit
// the JSON by hand: open, label or close the issue instead.
const ISSUES_URL = `https://github.com/${todos.repo}/issues`;

function itemsFor(source: PackageSourceId) {
  return todos.items.filter((item) => item.sources.includes(source));
}

export const useSourceCounts = routeLoader$(async (requestEvent) =>
  getSourceCounts(resolveServerEnv(requestEvent.platform)),
);

export default component$(() => {
  const counts = useSourceCounts().value;
  // Most apps first: a gap in a big source matters to more people. Sources
  // with open items before the rest when counts are missing (no dataset).
  const sources = ALL_PACKAGE_SOURCE_IDS.toSorted(
    (a, b) => (counts[b] ?? 0) - (counts[a] ?? 0) || itemsFor(b).length - itemsFor(a).length,
  );
  const synced = new Date(todos.syncedAt).toLocaleDateString("en", { dateStyle: "medium" });

  return (
    <div class="flex flex-col gap-8">
      <div class="flex flex-col gap-3">
        <h1 class="text-3xl font-bold">Per-source to-do</h1>
        <p class="text-base-content/70">
          What each source still misses for a complete merge: a beta branch not fetched, a stable
          release not connected, a filter letting non-apps through. Every item is its own issue on
          the catalog repo, labelled with its source — pick one up, or open a new one with the right{" "}
          <code class="text-sm">source:&lt;id&gt;</code> label.
        </p>
        <p class="text-sm text-base-content/60">
          Item list synced {synced} ·{" "}
          <a
            href={`${ISSUES_URL}?q=is%3Aissue+is%3Aopen+label%3Asource%3A*`}
            target="_blank"
            rel="noopener"
            class="link link-primary"
          >
            all open items on GitHub
          </a>{" "}
          ·{" "}
          <a href="/docs/sources/" class="link link-primary">
            how each source is read
          </a>
        </p>
      </div>

      <div class="overflow-x-auto">
        <table class="table">
          <thead>
            <tr>
              <th>Source</th>
              <th class="text-right">Apps</th>
              <th>Open items</th>
            </tr>
          </thead>
          <tbody>
            {sources.map((source) => {
              const items = itemsFor(source);
              const count = counts[source];
              return (
                <tr key={source} class="align-top">
                  <td class="whitespace-nowrap">
                    <a
                      href={`/browse/?source=${encodeURIComponent(source)}`}
                      class="link link-hover font-medium"
                    >
                      {SOURCE_LABELS[source]}
                    </a>
                    <div class="text-xs text-base-content/50 font-mono">{source}</div>
                  </td>
                  <td class="text-right tabular-nums">
                    {count === undefined ? "—" : count.toLocaleString("en")}
                  </td>
                  <td>
                    {items.length === 0 ? (
                      <span class="text-base-content/40">None tracked yet</span>
                    ) : (
                      <ul class="flex flex-col gap-1">
                        {items.map((item) => (
                          <li key={item.number} class="flex gap-2">
                            <LuCircleDot class="text-success shrink-0 mt-1" />
                            <a
                              href={item.url}
                              target="_blank"
                              rel="noopener"
                              class="link link-hover"
                            >
                              {item.title} <span class="text-base-content/50">#{item.number}</span>
                            </a>
                          </li>
                        ))}
                      </ul>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <p class="text-sm text-base-content/60">
        "Apps" counts published apps with at least one package from that source, after filtering and
        merging — not the raw package count. Finer coverage figures (share classified, icons and
        licenses filled) need the catalog to publish them per source first.
      </p>
    </div>
  );
});

export const head: DocumentHead = {
  title: "Per-source to-do — Tuxery",
  meta: [
    {
      name: "description",
      content:
        "What each of Tuxery's sources still misses for a complete merge, one GitHub issue per item.",
    },
  ],
};
